create extension if not exists pgcrypto;
create table if not exists public.vpi_management_users(user_id uuid primary key references auth.users(id) on delete cascade,email text not null unique,created_at timestamptz not null default now());
create or replace function public.is_vpi_manager() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.vpi_management_users where user_id=auth.uid()); $$;
revoke all on function public.is_vpi_manager() from public; grant execute on function public.is_vpi_manager() to authenticated;
create table if not exists public.inventory_transactions(id uuid primary key default gen_random_uuid(),movement_date date not null,movement_type text not null check(movement_type in('opening','receipt','issue','return','scrap','adjustment_in','adjustment_out')),material_name text not null,part_number text not null default '',grade text not null default '',diameter text not null default '',batch_no text not null default '',work_order text not null default '',quantity numeric(14,3) not null check(quantity>0),uom text not null default 'kg',unit_rate numeric(14,2),notes text not null default '',created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create index if not exists inv_date_idx on public.inventory_transactions(movement_date);create index if not exists inv_material_idx on public.inventory_transactions(material_name);create index if not exists inv_batch_idx on public.inventory_transactions(batch_no);
create table if not exists public.production_entries(id uuid primary key default gen_random_uuid(),production_date date not null,batch_no text not null,work_order text not null default '',part_number text not null default '',planned_qty numeric(14,3) not null default 0 check(planned_qty>=0),actual_qty numeric(14,3) not null default 0 check(actual_qty>=0),rejected_qty numeric(14,3) not null default 0 check(rejected_qty>=0),machine text not null default '',shift text not null default '',notes text not null default '',created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create index if not exists prod_date_idx on public.production_entries(production_date);create index if not exists prod_batch_idx on public.production_entries(batch_no);
alter table public.vpi_management_users enable row level security;alter table public.inventory_transactions enable row level security;alter table public.production_entries enable row level security;
drop policy if exists "Manager reads own allowlist row" on public.vpi_management_users;create policy "Manager reads own allowlist row" on public.vpi_management_users for select to authenticated using(user_id=auth.uid());
drop policy if exists "Managers manage inventory" on public.inventory_transactions;create policy "Managers manage inventory" on public.inventory_transactions for all to authenticated using(public.is_vpi_manager()) with check(public.is_vpi_manager());
drop policy if exists "Managers manage production" on public.production_entries;create policy "Managers manage production" on public.production_entries for all to authenticated using(public.is_vpi_manager()) with check(public.is_vpi_manager());
grant select on public.vpi_management_users to authenticated;grant select,insert,update,delete on public.inventory_transactions,public.production_entries to authenticated;
